#!/usr/bin/env bash
# Builds the core from this checkout for Swift, which has no core until one is built. (Go
# needs nothing: its core is the Go translation committed in go/internal/core, regenerated by
# `go generate` in go/. PHP builds its own extension: `cargo php-ext` in rust/, then
# `composer test` in php/.) It touches nothing committed: the Swift bundle lands in
# swift/HyperUuidCore.artifactbundle/, which git ignores but for its include/.
#
#   Swift  swift/HyperUuidCore.artifactbundle/     swift test
#
# The archives come from the forge's build-static-libs.sh, which writes into a repository
# root's swift/ tree, so it is handed a stand-in root, rust/target/local-core/, whose rust/ is
# this checkout's own and whose swift/ is the output directory above; the Swift bundle is
# then copied into the in-tree bundle, where Package.swift picks the archive for the host
# triple.
#
# With ANDROID=1 it also builds the two Android archives (aarch64 and x86_64), which the Swift
# SDK for Android links, for a suite cross-compiled and run on an emulator or device
# (.github/scripts/android_build_suite.sh).
#
# usage: .github/scripts/local-core.sh    (FORGE=<path> if the SkunkWerkx/.github checkout
#                                          is not ../.github or ../HyperForge beside this
#                                          repository)
set -euo pipefail

repo="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
build_static_libs=.github/actions/static-libs/build-static-libs.sh
if [ -n "${FORGE:-}" ]; then
  forge="$FORGE/$build_static_libs"
elif [ -f "$repo/../.github/$build_static_libs" ]; then
  forge="$repo/../.github/$build_static_libs"
else
  forge="$repo/../HyperForge/$build_static_libs"
fi
[ -f "$forge" ] || { echo "error: $forge not found; set FORGE to the SkunkWerkx/.github checkout" >&2; exit 1; }

case "$(uname -s)-$(uname -m)" in
  Linux-x86_64) targets=(x86_64-unknown-linux-musl x86_64-unknown-linux-gnu) ;;
  Linux-aarch64) targets=(aarch64-unknown-linux-musl aarch64-unknown-linux-gnu) ;;
  Darwin-x86_64) targets=(x86_64-apple-darwin) ;;
  Darwin-arm64) targets=(aarch64-apple-darwin) ;;
  *) echo "error: no local core for $(uname -s)-$(uname -m)" >&2; exit 1 ;;
esac

[ "${ANDROID:-}" = 1 ] && targets+=(aarch64-linux-android x86_64-linux-android)

(cd "$repo/rust" && cargo cdylib)

stand_in="$repo/rust/target/local-core"
bundle="$stand_in/swift/HyperUuidCore.artifactbundle"
mkdir -p "$bundle"
ln -sfn ../.. "$stand_in/rust"
ln -sfn "$repo/swift/HyperUuidCore.artifactbundle/include" "$bundle/include"
bash "$forge" hyperuuid HyperUuid "$stand_in" "${targets[@]}"
for variant in "$bundle"/*/; do
  [ "$(basename "$variant")" = include ] && continue
  mkdir -p "$repo/swift/HyperUuidCore.artifactbundle/$(basename "$variant")"
  cp "$variant"* "$repo/swift/HyperUuidCore.artifactbundle/$(basename "$variant")/"
done
cp "$bundle/info.json" "$repo/swift/HyperUuidCore.artifactbundle/info.json"

cat <<EOF

local core built from $(git -C "$repo" rev-parse --short HEAD)$(git -C "$repo" diff --quiet HEAD -- rust || echo ' plus uncommitted changes'):
  swift/  swift test
EOF
